{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Tocotrienol-rich fraction of palm oil, a lipophilic isoprenoid with a chromanol ring and long side chain, is reported to have poor oral bioavailability, supporting low F for the similarly lipophilic quinone-polyisoprenoid query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Lycopene, a long-chain carotenoid, showed only ~2.6% systemic availability from capsules in humans, indicating that highly lipophilic long-chain isoprenoids often have very low oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Lycopene from tomato paste showed only 0.17% systemic availability in humans, reinforcing the poor absorption typical of large lipophilic isoprenoid molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Phytoene, a C40 carotenoid, was estimated to have 58% bioavailability in humans, suggesting that some long-chain isoprenoids can be absorbed; however, this is a hydrocarbon without the quinone head group and may not transfer to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "All-trans lycopene showed 23.2% bioavailability in a 13C-labeled study, indicating that certain formulations/isomer mixtures can reach F ≥ 20%, but lycopene is structurally distinct from the quinone query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a ubiquinone-like molecule (CoQ10-type) with an extremely long, lipophilic isoprenoid chain, high MW (~863 Da), and very high logP. The most transferable experimental evidence—tocotrienols (poor bioavailability) and most lycopene studies (very low systemic availability)—supports low oral bioavailability. The high phytoene and some lycopene values are for hydrocarbon carotenoids without the quinone core and are less transferable. The physicochemical prior (low) is consistent with the weight of evidence, so F < 20% is the better-supported prediction.",
  "evidence_gaps": [
    "No direct experimental bioavailability record for ubiquinone/CoQ10 itself was provided.",
    "The tocotrienol record is for a complex fraction rather than a pure compound, limiting quantitative transfer.",
    "Carotenoid bioavailability values vary widely with formulation, food matrix, and measurement method, making cross-compound extrapolation uncertain."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "moderate",
      "card_ids": ["C12"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "tocotrienol/isoprenoid lipid"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C14"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "carotenoid"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C03"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "carotenoid"
    }
  ],
  "revision_action": "initial"
}

